lemmas.∘-resp-≈:
{A B : Obj} {C = i₁ : Obj} {f = j : B ⇒ i₁} {h = k : B ⇒ i₁}
{g = g₁ : A ⇒ B} {i = i₂ : A ⇒ B} →
j ≈ k → g₁ ≈ i₂ → j ∘ g₁ ≈ k ∘ i₂

